/* Account screens use the real Supabase-backed StudyCloud client. */
(()=>{
  'use strict';
  const safe=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let mode='signin',lastStatus={configured:false,user:null,status:'initializing'},context=null,notice=null,busy=false,renderQueued=false,pendingOTP=null,otpTimer=null;
  function message(text,error=false){notice={text,error};const box=document.querySelector('#auth-message');if(box){box.textContent=text;box.className='auth-message'+(error?' error':'');box.hidden=false}}
  const githubMode=s=>s.authProvider==='github'||(!s.authProvider&&window.STUDY_CLOUD_CONFIG?.authProvider==='github');
  const instantMode=s=>s.emailSignupMode==='instant'||(!s.emailSignupMode&&window.STUDY_CLOUD_CONFIG?.emailSignupMode==='instant'&&!githubMode(s));
  const otpMode=s=>s.emailSignupMode==='otp'||(!s.emailSignupMode&&window.STUDY_CLOUD_CONFIG?.emailSignupMode==='otp'&&!githubMode(s));
  const settingsMode=s=>instantMode(s)||otpMode(s);
  const deliveryAllowed=s=>s.emailDeliveryReady??window.STUDY_CLOUD_CONFIG?.emailDeliveryReady??!otpMode(s);
  const remainingSeconds=()=>pendingOTP?Math.max(0,Math.ceil((pendingOTP.resendAt-Date.now())/1000)):0;
  const recoveryAllowed=s=>s.passwordRecoveryEnabled??window.STUDY_CLOUD_CONFIG?.passwordRecoveryEnabled??true;
  function setBusy(){context?.host.querySelectorAll('[data-auth-mode],#auth-submit,#auth-github,#auth-retry,#auth-have-code,#otp-submit,#otp-resend,#otp-back,#sync-now,#sign-out,#import-guest,[data-conflict-path]').forEach(b=>{b.disabled=busy||(b.id==='auth-submit'&&(!lastStatus.configured||!lastStatus.recovery&&mode==='signup'&&settingsMode(lastStatus)&&(lastStatus.emailSignupReady!==true||lastStatus.emailSignupChecking||otpMode(lastStatus)&&!deliveryAllowed(lastStatus))||!lastStatus.recovery&&mode==='reset'&&!deliveryAllowed(lastStatus)))||(b.id==='auth-github'&&(!lastStatus.configured||lastStatus.oauthReady!==true||lastStatus.oauthChecking||lastStatus.status==='oauth-redirect'))||(b.id==='auth-retry'&&(!lastStatus.configured||lastStatus.oauthChecking||lastStatus.emailSignupChecking))||(b.id==='auth-have-code'&&!lastStatus.configured)||(b.id==='otp-submit'&&!lastStatus.configured)||(b.id==='otp-resend'&&(!deliveryAllowed(lastStatus)||remainingSeconds()>0))})}
  function readableError(error){const t=String(error?.message||error||'操作未能完成，请重试。');if(/Invalid login credentials/i.test(t))return'邮箱或密码不正确，请检查后再试。';if(/Email not confirmed|请先完成邮箱验证/i.test(t))return otpMode(lastStatus)?'邮箱尚未验证，请先输入注册验证码完成验证。':'邮箱尚未验证，请先完成邮箱验证后再登录。';if(/(?:token|otp|verification code).*(?:expired|invalid)|(?:expired|invalid).*(?:token|otp|verification code)/i.test(t))return'验证码无效或已过期，请重新输入，或获取最新验证码。';if(/rate limit|too many requests/i.test(t))return'请求较频繁，请稍后再试。';if(/Failed to fetch|NetworkError/i.test(t))return'网络暂时无法连接，请检查网络后重试。';return t}
  const showValue=cell=>{const value=cell&&typeof cell==='object'&&'deleted'in cell?(cell.deleted?undefined:cell.value):cell;return value===undefined?'（已删除）':typeof value==='string'?value:JSON.stringify(value,null,2)};
  function fieldLabel(x){let p;try{p=JSON.parse(x.path)}catch{return '学习记录'}const names={drafts:'作答草稿',essays:'作文',tasks:'学习任务',words:'词汇状态',results:'听力成绩',mistakes:'错题',read:'专题阅读',settings:'个人设置',mock:'模拟卷',prompt:'题目',draft:'草稿',answers:'作答',plan:'学习计划',day:'学习日'};return p.map(k=>names[k]||k).join(' · ')}
  async function run(button,action,done){if(button.disabled||busy)return;busy=true;setBusy();const before=button.textContent;button.textContent='处理中…';try{const result=await action();if(done)done(result)}catch(error){message(readableError(error),true)}finally{busy=false;if(renderQueued&&context&&location.hash==='#account'){renderQueued=false;render(context.host,context.ctx)}else{setBusy();if(button.isConnected)button.textContent=before}}}
  function render(host,ctx){clearTimeout(otpTimer);otpTimer=null;if(mode==='reset'&&!recoveryAllowed(lastStatus)&&!lastStatus.recovery)mode='signin';const oldForm=context?.host===host&&context.mode===mode&&context.recovery===!!lastStatus.recovery?host.querySelector('#auth-form'):null;const fields=oldForm?Object.fromEntries([...oldForm.elements].filter(el=>el.name).map(el=>[el.name,el.value])):null;context={host,ctx,configured:lastStatus.configured,mode,recovery:!!lastStatus.recovery};const status=lastStatus,c=window.StudyCloud;
    host.innerHTML=ctx.heading('YOUR PERSONAL ORBIT',status.user?'你的进度，随你同行。':'登录，接续每一次进步。',status.user?'电脑练习，手机复习。同一账号，接续你的任务、错题和草稿。':githubMode(status)?'使用 GitHub 登录，跨设备接续你的学习记录。也可以先以游客身份体验。':'邮箱注册个人账号，学习记录属于你。也可以先以游客身份体验。')+
      `<div class="settings-grid"><section class="panel account-panel">${status.user&&!status.recovery?profile(status):pendingOTP&&!status.recovery?otpForm(status):form(status)}<div id="auth-message" class="auth-message" role="status" aria-live="polite" hidden></div></section><section class="panel profile-card"><div class="card-kicker">ONE ACCOUNT · EVERY DEVICE</div><h2>把努力，留在你的轨道里。</h2><div class="account-benefits"><p><span>01</span><strong>自动接续进度</strong><small>任务、词汇、听力答案与写作草稿随账号保存。</small></p><p><span>02</span><strong>每个人的独立空间</strong><small>公开课程，个人进度。其他账号不能读取你的学习记录。</small></p><p><span>03</span><strong>离线也能继续</strong><small>断网时先保存在当前设备，重新联网后尝试同步。</small></p></div><p class="hint">在公共电脑上学习后，请退出账号。访客进度不会自动导入登录账号，你可以登录后自行选择导入。</p><button class="secondary" data-go="home">${status.user?'返回学习空间':'先体验课程'} →</button></section></div>${status.user?conflicts(c?.getConflicts?.()||[]):''}`;
    host.querySelectorAll('[data-auth-mode]').forEach(b=>b.onclick=()=>{if(busy||b.dataset.authMode==='reset'&&!recoveryAllowed(lastStatus))return;notice=null;mode=b.dataset.authMode;render(host,ctx)});
    const f=host.querySelector('#auth-form');if(f&&fields)for(const [key,value] of Object.entries(fields)){if(f.elements[key])f.elements[key].value=value}if(f)f.onsubmit=async event=>{event.preventDefault();if(busy)return;const intent=status.recovery?'recovery':mode,b=host.querySelector('#auth-submit'),email=f.elements.email?.value.trim(),password=f.elements.password?.value;if(['signup','recovery'].includes(intent)&&password!==f.elements.confirmPassword.value){message('两次输入的密码不一致。',true);return}await run(b,()=>intent==='recovery'?c.updatePassword(password):intent==='reset'?c.resetPassword(email):intent==='signup'?c.signUp(email,password):c.signIn(email,password),result=>{if(intent==='recovery'){mode='signin';render(host,ctx);message('密码已更新，你可以继续使用当前账号。')}else if(intent==='reset'){if(otpMode(lastStatus)){beginOTP('recovery',email,host,ctx);message('找回验证码请求已提交。如果该邮箱已注册，请查看邮件及垃圾邮件。')}else message('如果这个邮箱已经注册，我们会向它发送重置邮件，请检查收件箱及垃圾邮件。')}else if(intent==='signup'){if(otpMode(lastStatus)){f.reset();beginOTP('signup',email,host,ctx);message('注册验证码请求已提交。若该邮箱可用于注册，请查收邮件并填写验证码。')}else if(lastStatus.user||result?.user){ctx.toast('账号已创建并登录，欢迎进入个人学习空间');location.hash='home'}else if(instantMode(lastStatus)){message('未完成直接注册，尚未收到登录会话。请重试；若已有账号，请直接登录。',true)}else{message('注册请求已提交。请打开邮箱中的确认链接后登录，并检查垃圾邮件。');if(f.isConnected)f.reset()}}else if(lastStatus.user){ctx.toast('登录成功，已进入你的个人学习空间');location.hash='home'}})};
    const haveCode=host.querySelector('#auth-have-code');if(haveCode)haveCode.onclick=()=>{if(busy)return;const email=host.querySelector('#auth-email');if(!email?.value.trim()||!email.checkValidity()){message('请先在邮箱账号栏填写注册时使用的邮箱。',true);email?.focus();return}host.querySelectorAll('input[type="password"]').forEach(input=>{input.value=''});beginOTP('signup',email.value,host,ctx,0)};
    bindOTP(host,ctx,c);
    const github=host.querySelector('#auth-github');if(github)github.onclick=()=>run(github,()=>c.signInWithGitHub(),()=>message('正在前往 GitHub 授权登录，请完成后返回本站。'));
    const retry=host.querySelector('#auth-retry');if(retry)retry.onclick=()=>{notice=null;run(retry,()=>c.refreshAuthSettings(),()=>{renderQueued=true})};
    const sync=host.querySelector('#sync-now');if(sync)sync.onclick=()=>run(sync,()=>c.syncNow(),()=>message('已完成同步检查。'));
    const logout=host.querySelector('#sign-out');if(logout)logout.onclick=()=>run(logout,()=>c.signOut(),()=>{ctx.toast('已退出账号');mode='signin';render(host,ctx)});
    const guest=host.querySelector('#import-guest');if(guest)guest.onclick=()=>{if(confirm('把此设备的游客练习导入当前账号？已有不同内容会提示你选择，建议先导出备份。'))run(guest,()=>c.importGuest(),()=>{message('已处理游客进度，请检查同步状态及冲突提示。');render(host,ctx)})};
    host.querySelectorAll('[data-conflict-path]').forEach(b=>b.onclick=()=>run(b,()=>c.resolveConflict(b.dataset.conflictPath,b.dataset.choice),()=>render(host,ctx)));
    if(notice)message(notice.text,notice.error);setBusy();if(pendingOTP&&!status.user&&!status.recovery)tickOTP();
  }
  function oauthForm(s){const ready=s.configured&&s.oauthReady===true&&!s.oauthChecking;const title=!s.configured?'账号服务尚未启用':s.oauthChecking?'正在确认登录服务':s.oauthReady===false?'GitHub 登录待配置':s.oauthReady!==true?'未能确认 GitHub 登录服务':'使用 GitHub 登录';const note=!s.configured?'账号服务配置完成后即可登录。现在可以先学习，游客进度保存在当前浏览器。':s.oauthMessage||(ready?'登录后可在手机和电脑之间接续进度。':'可以重试确认状态，或先以游客身份继续学习。');return `<div class="auth-tabs"><strong>GITHUB · 个人学习账号</strong></div><div class="notice" role="status"><strong>${safe(title)}</strong><p>${safe(note)}</p></div><button id="auth-github" class="primary auth-submit" type="button" ${!ready?'disabled':''}>${s.status==='oauth-redirect'?'正在前往 GitHub…':'使用 GitHub 继续'} ↗</button><div class="account-actions">${s.configured?'<button id="auth-retry" type="button" class="quiet">重新检测登录服务</button>':''}<button class="quiet" data-go="home">以游客身份继续学习</button></div><p class="password-note">GitHub 负责登录验证。本站不会要求你的 GitHub 密码，也不会申请仓库访问权限。</p>`}
  function form(s){
    const recovery=!!s.recovery,instant=instantMode(s),otp=otpMode(s),needsSettings=settingsMode(s),delivery=deliveryAllowed(s);
    if(githubMode(s)&&!recovery)return oauthForm(s);
    const ready=s.emailSignupReady===true&&!s.emailSignupChecking&&(!otp||delivery);
    const signupNote=needsSettings&&!recovery&&s.configured?`<div class="notice" id="email-signup-state" role="status"><strong>${otp&&!delivery?'验证码邮件服务待配置':s.emailSignupChecking?'正在确认注册设置':ready?otp?'邮箱验证码注册已开放':'邮箱密码注册已开放':s.emailSignupReady===false?'注册即将开放':'未能确认注册设置'}</strong><p>${safe(otp&&!delivery?'注册与邮件找回将在邮件服务启用后开放；已有账号仍可登录。':s.emailSignupMessage||(ready?otp?'注册需填写邮件验证码，验证后即可登录。':'注册无需验证邮件，邮箱仅作登录账号。':'已有账号仍可登录；也可以先以游客身份学习。'))}</p><button id="auth-retry" class="quiet" type="button">重新检测注册状态</button></div>`:'';
    return `<div class="auth-tabs">${!recovery?[['signin','登录'],['signup','创建账号']].map(([k,t])=>`<button type="button" data-auth-mode="${k}" class="${mode===k?'active':''}">${t}</button>`).join(''):'<strong>设置新密码</strong>'}</div>${!s.configured?'<div class="notice">账号服务尚未启用。管理员完成云服务配置后即可注册与同步；现在可以先以游客身份体验。</div>':''}${signupNote}<form id="auth-form" class="auth-form">${!recovery?'<label for="auth-email">邮箱账号</label><input id="auth-email" name="email" type="email" autocomplete="email" required maxlength="254" placeholder="you@example.com">':''}${mode!=='reset'||recovery?`<label for="auth-password">${recovery?'新密码':'密码'}</label><input id="auth-password" name="password" type="password" autocomplete="${mode==='signup'||recovery?'new-password':'current-password'}" required minlength="${mode==='signup'||recovery?8:1}" maxlength="128" placeholder="${mode==='signup'||recovery?'至少 8 个字符':'输入你的密码'}">`:''}${mode==='signup'||recovery?'<label for="auth-confirm">确认密码</label><input id="auth-confirm" name="confirmPassword" type="password" autocomplete="new-password" required minlength="8" maxlength="128" placeholder="再次输入密码">':''}<button id="auth-submit" class="primary auth-submit" type="submit" ${!s.configured||!recovery&&(mode==='signup'&&needsSettings&&!ready||mode==='reset'&&!delivery)?'disabled':''}>${recovery?'更新密码':mode==='signup'?otp?'注册并发送验证码':'创建我的账号':mode==='reset'?otp?'发送找回验证码':'发送重置邮件':'登录我的空间'} →</button></form><div class="account-actions">${otp&&!recovery?'<button id="auth-have-code" type="button" class="quiet">已有注册验证码</button>':''}${!recovery&&recoveryAllowed(s)?`<button type="button" class="quiet" data-auth-mode="${mode==='reset'?'signin':'reset'}">${mode==='reset'?'返回登录':'忘记密码？'}</button>`:''}<button class="quiet" data-go="home">以游客身份浏览</button></div>${otp&&!recovery?'<p class="password-note">注册需要邮箱验证码，请使用能收信的邮箱。验证后可用邮箱和密码登录，也可通过验证码找回密码。</p>':instant&&!recovery?'<p class="password-note">邮箱仅作为登录账号；直接注册无需验证邮件。</p>':''}${!recoveryAllowed(s)?'<p class="password-note">暂不支持邮件找回密码，请妥善保存账号和密码。</p>':''}<p class="password-note">密码由身份服务安全处理，不会写入课程仓库或学习进度文件。</p>`;
  }
  function beginOTP(type,email,host,ctx,resendDelay=60000){pendingOTP={type,email:email.trim(),resendAt:Date.now()+resendDelay};notice=null;if(location.hash==='#account')render(host,ctx)}
  function otpForm(s){const signup=pendingOTP.type==='signup';return `<div class="auth-tabs"><strong>${signup?'验证邮箱 · 完成注册':'验证邮箱 · 找回密码'}</strong></div><p>验证码对应邮箱：<strong class="break-word">${safe(pendingOTP.email)}</strong>。${signup?'若该邮箱可用于注册':'若该邮箱已注册'}，请查看收件箱和垃圾邮件。</p><form id="otp-form" class="auth-form"><label for="auth-otp">邮件验证码</label><input id="auth-otp" name="token" type="text" inputmode="numeric" autocomplete="one-time-code" minlength="6" maxlength="8" pattern="[0-9]{6,8}" required placeholder="输入邮件中的 6–8 位数字"><button id="otp-submit" type="submit" class="primary auth-submit">${signup?'验证并进入学习空间':'验证并设置新密码'} →</button></form><div class="account-actions"><button id="otp-resend" type="button" class="quiet">重新发送验证码</button><button id="otp-back" type="button" class="quiet">更换邮箱 / 返回</button></div><p class="password-note">验证码只用于本次验证，不会保存在学习进度中。重发后请使用最新邮件中的验证码。</p>${!deliveryAllowed(s)?'<div class="notice">邮件服务暂未就绪，当前不能重发验证码；已有有效验证码仍可验证。</div>':''}`}
  function tickOTP(){if(!pendingOTP||location.hash!=='#account'||!context?.host.querySelector('#otp-form'))return;const b=context.host.querySelector('#otp-resend'),seconds=remainingSeconds();b.textContent=seconds?`${seconds} 秒后可重发`:'重新发送验证码';setBusy();otpTimer=setTimeout(tickOTP,1000)}
  function bindOTP(host,ctx,c){
    const form=host.querySelector('#otp-form');if(!form)return;
    form.onsubmit=event=>{event.preventDefault();if(busy||!pendingOTP)return;const token=form.elements.token.value.trim();if(!/^\d{6,8}$/.test(token)){message('请输入邮件中的 6–8 位数字验证码。',true);return}const current={...pendingOTP};form.elements.token.value='';run(host.querySelector('#otp-submit'),()=>current.type==='signup'?c.verifySignup(current.email,token):c.verifyRecovery(current.email,token),result=>{if(!result?.user&&!lastStatus.user){message('验证未完成，尚未收到登录会话，请重试。',true);return}pendingOTP=null;notice=null;clearTimeout(otpTimer);if(current.type==='recovery'){mode='signin';render(host,ctx);message('邮箱验证已完成，请设置新密码。')}else{ctx.toast('邮箱验证成功，欢迎进入个人学习空间');location.hash='home'}})};
    const resend=host.querySelector('#otp-resend');resend.onclick=()=>{if(!pendingOTP)return;run(resend,()=>{pendingOTP.resendAt=Date.now()+60000;return pendingOTP.type==='signup'?c.resendSignup(pendingOTP.email):c.resetPassword(pendingOTP.email)},()=>{message(pendingOTP.type==='signup'?'验证码重发请求已提交。若该邮箱可用于注册，请查看最新邮件。':'验证码重发请求已提交。若该邮箱已注册，请查看最新邮件。');render(host,ctx)})};
    host.querySelector('#otp-back').onclick=()=>{if(busy)return;const current=pendingOTP;pendingOTP=null;clearTimeout(otpTimer);notice=null;mode=current.type==='signup'?'signup':'reset';render(host,ctx);const email=host.querySelector('#auth-email');if(email)email.value=current.email};
  }
  function profile(s){return `<div class="row-between"><span class="status-chip">PERSONAL ACCOUNT</span><span class="sync-state" data-state="${safe(s.status)}">${safe(s.message||'同步准备中')}</span></div><div class="account-avatar">${safe((s.user.email||'U')[0].toUpperCase())}</div><h2 class="break-word">${safe(s.user.email||'已登录')}</h2><p class="hint">${s.lastSyncAt?'最近同步：'+new Date(s.lastSyncAt).toLocaleString('zh-CN'):'进度会在练习后自动保存。'}</p>${s.pending?'<div class="notice">还有本地变更等待上传，请保持页面打开并检查网络。</div>':''}<div class="button-row"><button id="sync-now" class="primary">立即同步</button><button class="secondary" data-go="settings">备份与偏好</button></div>${s.guestAvailable?'<button class="quiet" id="import-guest">将此设备游客进度导入当前账号 →</button>':''}<div class="button-row"><button id="sign-out" class="quiet">退出登录</button></div>${s.recovery?'<button class="secondary" data-auth-mode="recover">设置新密码</button>':''}`}
  function conflicts(items){if(!items.length)return'';return `<section class="panel space-top"><h2>选择要保留的内容</h2><p class="hint">两台设备修改了同一项。两份内容都已保留，请比较后选择。</p>${items.map(x=>`<div class="conflict-card"><h3>${safe(fieldLabel(x))}</h3><div class="two-grid"><div><span class="tag">这台设备</span><pre>${safe(showValue(x.local).slice(0,1200))}</pre><button class="secondary small" data-conflict-path="${safe(x.path)}" data-choice="local">保留本机内容</button></div><div><span class="tag">云端</span><pre>${safe(showValue(x.remote).slice(0,1200))}</pre><button class="primary small" data-conflict-path="${safe(x.path)}" data-choice="remote">使用云端内容</button></div></div></div>`).join('')}</section>`}
  window.AccountUI={render,onStatus(s){const providerChanged=['authProvider','oauthReady','oauthChecking','oauthMessage','emailSignupMode','emailSignupReady','emailSignupChecking','emailSignupMessage','passwordRecoveryEnabled','emailDeliveryReady'].some(k=>s[k]!==lastStatus[k]);const identityChanged=(s.user?.id||null)!==(lastStatus.user?.id||null)||!!s.recovery!==!!lastStatus.recovery;lastStatus=s;if(identityChanged){notice=null;if(s.user||s.recovery){pendingOTP=null;clearTimeout(otpTimer)}}if(location.hash==='#account'&&context){if(identityChanged||s.configured!==context.configured||providerChanged){if(busy)renderQueued=true;else render(context.host,context.ctx);return}const active=document.activeElement;if(s.user&&!s.recovery&&(!active||!context.host.contains(active)||!['INPUT','TEXTAREA'].includes(active.tagName))){if(busy)renderQueued=true;else render(context.host,context.ctx)}}},getStatus:()=>lastStatus};
})();
